use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () , Box < dyn std :: error :: Error > > { let args : Vec < String > = std :: env :: args () . collect () ; if args . len () < 3 { println ! ("Usage: {} <input_dir> <output_file>" , args [0]) ; return Ok (()) ; } let input_dir = & args [1] ; let output_file = & args [2] ; println ! ("👹 Generating EPIC Rust to Monster Group Transformation Report...") ; println ! ("📂 Analyzing: {}" , input_dir) ; let mut signature_frequencies : HashMap < String , u64 > = HashMap :: new () ; let mut processed_files = 0 ; fn scan_directory (dir : & str , signatures : & mut HashMap < String , u64 > , processed : & mut usize) -> Result < () , Box < dyn std :: error :: Error > > { for entry in fs :: read_dir (dir) ? { let entry = entry ? ; let path = entry . path () ; if path . is_dir () { scan_directory (path . to_str () . unwrap () , signatures , processed) ? ; } else if path . extension () . and_then (| s | s . to_str ()) == Some ("rs") { if let Ok (content) = fs :: read_to_string (& path) { let signature = extract_signature_from_content (& content) ; if ! signature . is_empty () { * signatures . entry (signature) . or_insert (0) += 1 ; * processed += 1 ; if * processed % 1000 == 0 { println ! ("📊 Processed {} files..." , processed) ; } } } } } Ok (()) } scan_directory (input_dir , & mut signature_frequencies , & mut processed_files) ? ; println ! ("✅ Processed {} files" , processed_files) ; println ! ("🔄 Generating Monster Group analysis...") ; let report = generate_epic_monster_report (& signature_frequencies , processed_files) ; fs :: write (output_file , report) ? ; println ! ("🎉 EPIC SUCCESS!") ; println ! ("👹 Rust to Monster Group Transformation Report written to: {}" , output_file) ; println ! ("📊 Total unique signatures: {}" , signature_frequencies . len ()) ; println ! ("🔢 Total declarations processed: {}" , signature_frequencies . values () . sum ::< u64 > ()) ; Ok (()) }
}